+package com.example.contact;
+
+import org.springframework.stereotype.Service;
+
+import java.time.Instant;
+import java.util.ArrayList;
+import java.util.Collections;
+import java.util.List;
+
+@Service
+public class ContactMessageService {
+
+    private final List<ContactMessage> messages = Collections.synchronizedList(new ArrayList<>());
+
+    public void add(String name, String email, String phone, String text) {
+        messages.add(0, new ContactMessage(name, email, phone, text, Instant.now()));
+    }
+
+    public List<ContactMessage> list() {
+        synchronized (messages) {
+            return List.copyOf(messages);
+        }
+    }
+}
