+package com.example.contact;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import java.util.List;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    private TextField name() {
+        return find(TextField.class).withLabel("Name").single();
+    }
+
+    private EmailField email() {
+        return find(EmailField.class).withLabel("Email").single();
+    }
+
+    private TextField phone() {
+        return find(TextField.class).withLabel("Phone").single();
+    }
+
+    private TextArea message() {
+        return find(TextArea.class).withLabel("Message").single();
+    }
+
+    private Button send() {
+        return find(Button.class).withText("Send").single();
+    }
+
+    @SuppressWarnings("unchecked")
+    private Grid<ContactMessage> grid() {
+        return (Grid<ContactMessage>) (Grid<?>) find(Grid.class).single();
+    }
+
+    private List<ContactMessage> rows() {
+        return grid().getDataProvider()
+                .fetch(new com.vaadin.flow.data.provider.Query<>())
+                .toList();
+    }
+
+    @Test
+    void contactViewHasHeadingLinkAndEmptyEnabledForm() {
+        navigate(ContactView.class);
+
+        assertEquals("Contact", find(H1.class).single().getText());
+
+        RouterLink about = find(RouterLink.class).withText("About").single();
+        assertTrue(test(about).getRoute().isPresent());
+
+        assertTrue(name().isEmpty());
+        assertTrue(email().isEmpty());
+        assertTrue(phone().isEmpty());
+        assertTrue(message().isEmpty());
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void aboutViewHasHeading() {
+        navigate(AboutView.class);
+        assertEquals("About", find(H1.class).single().getText());
+    }
+
+    @Test
+    void blankNameIsRejected() {
+        navigate(ContactView.class);
+        int before = rows().size();
+        test(email()).setValue("a@example.com");
+        test(message()).setValue("Hello there");
+
+        test(send()).click();
+
+        assertTrue(name().isInvalid());
+        assertEquals("Name is required", name().getErrorMessage());
+        assertTrue(find(Notification.class).all().isEmpty());
+        assertEquals(before, rows().size());
+    }
+
+    @Test
+    void invalidEmailIsRejected() {
+        navigate(ContactView.class);
+        test(name()).setValue("Ada");
+        test(email()).setValue("not-an-email");
+        test(message()).setValue("Hello there");
+
+        test(send()).click();
+
+        assertTrue(email().isInvalid());
+        assertEquals("Enter a valid e-mail address", email().getErrorMessage());
+    }
+
+    @Test
+    void missingEmailAndPhoneIsRejected() {
+        navigate(ContactView.class);
+        test(name()).setValue("Ada");
+        test(message()).setValue("Hello there");
+
+        test(send()).click();
+
+        assertTrue(email().isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email().getErrorMessage());
+    }
+
+    @Test
+    void phoneAloneIsEnough() {
+        navigate(ContactView.class);
+        int before = rows().size();
+        test(name()).setValue("Ada");
+        test(phone()).setValue("+1 555 0100");
+        test(message()).setValue("Hello there");
+
+        test(send()).click();
+
+        assertFalse(email().isInvalid());
+        assertEquals(before + 1, rows().size());
+    }
+
+    @Test
+    void blankMessageIsRejected() {
+        navigate(ContactView.class);
+        test(name()).setValue("Ada");
+        test(email()).setValue("a@example.com");
+
+        test(send()).click();
+
+        assertTrue(message().isInvalid());
+        assertEquals("Message is required", message().getErrorMessage());
+    }
+
+    @Test
+    void tooLongMessageIsRejected() {
+        navigate(ContactView.class);
+        test(name()).setValue("Ada");
+        test(email()).setValue("a@example.com");
+        test(message()).setValue("x".repeat(501));
+
+        test(send()).click();
+
+        assertTrue(message().isInvalid());
+        assertEquals("Message must be at most 500 characters", message().getErrorMessage());
+    }
+
+    @Test
+    void failedValidationKeepsTypedValuesAndSendsNothing() {
+        navigate(ContactView.class);
+        test(name()).setValue("");
+        test(email()).setValue("bad-email");
+        test(phone()).setValue("555");
+        test(message()).setValue("Hi");
+
+        test(send()).click();
+
+        assertEquals("", name().getValue());
+        assertEquals("bad-email", email().getValue());
+        assertEquals("555", phone().getValue());
+        assertEquals("Hi", message().getValue());
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void successfulSendClearsFormShowsNotificationAndAddsRow() {
+        navigate(ContactView.class);
+        int before = rows().size();
+        test(name()).setValue("Ada Lovelace");
+        test(email()).setValue("ada@example.com");
+        test(message()).setValue("Hello there");
+
+        test(send()).click();
+
+        String notificationText = test(find(Notification.class).single()).getText();
+        assertTrue(notificationText.contains("Message sent"), "Was: " + notificationText);
+
+        assertTrue(name().isEmpty());
+        assertTrue(email().isEmpty());
+        assertTrue(phone().isEmpty());
+        assertTrue(message().isEmpty());
+
+        assertFalse(send().isEnabled());
+
+        List<ContactMessage> rows = rows();
+        assertEquals(before + 1, rows.size());
+        assertEquals("Ada Lovelace", rows.get(0).name());
+        assertEquals("Hello there", rows.get(0).text());
+    }
+
+    @Test
+    void sendIsDisabledOnlyUntilNextEdit() {
+        navigate(ContactView.class);
+        test(name()).setValue("Ada Lovelace");
+        test(email()).setValue("ada@example.com");
+        test(message()).setValue("Hello there");
+        test(send()).click();
+
+        assertFalse(send().isEnabled());
+
+        test(name()).setValue("B");
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void enterKeySendsValidForm() {
+        navigate(ContactView.class);
+        int before = rows().size();
+        test(name()).setValue("Ada Lovelace");
+        test(email()).setValue("ada@example.com");
+        test(message()).setValue("Hello there");
+
+        fireShortcut(Key.ENTER);
+
+        assertTrue(name().isEmpty());
+        assertEquals(before + 1, rows().size());
+    }
+
+    @Test
+    void listedMessagesSurviveLeavingAndReturning() {
+        navigate(ContactView.class);
+        int before = rows().size();
+        test(name()).setValue("Ada Lovelace");
+        test(email()).setValue("ada@example.com");
+        test(message()).setValue("Hello there");
+        test(send()).click();
+
+        navigate(AboutView.class);
+        navigate(ContactView.class);
+
+        assertEquals(before + 1, rows().size());
+    }
+
+    @Test
+    void newestMessageIsFirstRow() {
+        navigate(ContactView.class);
+        test(name()).setValue("First");
+        test(email()).setValue("first@example.com");
+        test(message()).setValue("first message");
+        test(send()).click();
+
+        test(name()).setValue("Second");
+        test(email()).setValue("second@example.com");
+        test(message()).setValue("second message");
+        test(send()).click();
+
+        List<ContactMessage> rows = rows();
+        assertEquals("Second", rows.get(0).name());
+        assertEquals("First", rows.get(1).name());
+    }
+
+    @Test
+    void leavingWithEmptyFormDoesNotShowDialog() {
+        navigate(ContactView.class);
+
+        RouterLink about = find(RouterLink.class).withText("About").single();
+        test(about).click();
+
+        assertTrue(find(Dialog.class).all().isEmpty());
+        assertEquals("About", find(H1.class).single().getText());
+    }
+
+    @Test
+    void leavingWithUnsavedTextAsksFirstAndKeepEditingStays() {
+        navigate(ContactView.class);
+        test(name()).setValue("Ada");
+
+        RouterLink about = find(RouterLink.class).withText("About").single();
+        test(about).click();
+
+        Dialog dialog = find(Dialog.class).single();
+        Button keepEditing = find(Button.class, dialog).withText("Keep editing").single();
+        test(keepEditing).click();
+
+        assertTrue(find(Dialog.class).all().isEmpty());
+        assertEquals("Contact", find(H1.class).single().getText());
+        assertEquals("Ada", name().getValue());
+    }
+
+    @Test
+    void leavingWithUnsavedTextDiscardNavigatesAway() {
+        navigate(ContactView.class);
+        test(name()).setValue("Ada");
+
+        RouterLink about = find(RouterLink.class).withText("About").single();
+        test(about).click();
+
+        Dialog dialog = find(Dialog.class).single();
+        Button discard = find(Button.class, dialog).withText("Discard").single();
+        test(discard).click();
+
+        assertEquals("About", find(H1.class).single().getText());
+    }
+}
